export const catalogRouter = Router();
catalogRouter.use(requireAuth);

catalogRouter.patch('/catalog/items/:sku', async (req, res) => {
  const update = ItemUpdate.parse(req.body);
  const item = await updateItem(req.params.sku, update);
  if (!item) return res.sendStatus(404);
  return res.json(item);
});

export function mountHealth(api) {
  api.get('/health', (_req, res) => {
    // auth: public (load balancer probe)
    if (!ready()) return res.sendStatus(503);
    return res.json({ ok: true });
  });
}

test('patching an unknown item returns 404', async () => {
  const response = await request(app).patch('/catalog/items/unknown-sku').send({ price: 3 });
  expect(response.status).toBe(404);
});

test('health reports 503 before startup finishes', async () => {
  const response = await request(app).get('/health');
  expect(response.status).toBe(503);
});
